const normalise = (value: string) =>
  value
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, " ")
    .replace(/\s+/g, " ")
    .trim();

const HS_INDEX = HS_SUGGESTIONS.map((item) => ({
  item,
  code: item.code,
  normalisedCode: item.code,
  haystack: normalise([item.code, item.title, item.chapter, ...item.keywords, item.note ?? ""].join(" ")),
}));

export function findHsCodeSuggestions(query: string, limit = 6): HsCodeSuggestion[] {
  const safeLimit = Math.max(1, Math.min(limit, 50));
  const q = normalise(query);

  if (!q) {
    return HS_SUGGESTIONS.slice(0, safeLimit);
  }

  const tokens = q.split(" ").filter(Boolean);
  const numericQuery = q.replace(/\D/g, "");

  return HS_INDEX
    .map(({ item, code, haystack }) => {
      const exactCode = numericQuery.length > 0 && code === numericQuery;
      const codePrefix = numericQuery.length > 0 && code.startsWith(numericQuery);
      const exactTitle = normalise(item.title) === q;
      const exactKeyword = item.keywords.some((keyword) => normalise(keyword) === q);
      const phrase = haystack.includes(q);
      const tokenHits = tokens.reduce((hits, token) => hits + (haystack.includes(token) ? 1 : 0), 0);

      // Exact code/title matches always win. Prefix matches are useful for
      // entering 2, 4, 6, or 8 digit HS-code prefixes.
      const score =
        (exactCode ? 1000 : 0) +
        (exactTitle ? 300 : 0) +
        (exactKeyword ? 200 : 0) +
        (codePrefix ? 150 : 0) +
        (phrase ? 80 : 0) +
        tokenHits * 15;

      return { item, score };
    })
    .filter(({ score }) => score > 0)
    .sort((a, b) => b.score - a.score || a.item.code.localeCompare(b.item.code))
    .slice(0, safeLimit)
    .map(({ item }) => item);
}
